CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS data_sources (id text PRIMARY KEY, name text NOT NULL, url text, type text NOT NULL, licence text NOT NULL, retrieved_at date NOT NULL, fields_fed jsonb NOT NULL, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS skills (id text PRIMARY KEY, name text UNIQUE NOT NULL, normalized_name text UNIQUE NOT NULL, category text NOT NULL, aliases text[] NOT NULL DEFAULT '{}', payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS employees (id text PRIMARY KEY, name text NOT NULL, "current_role" text NOT NULL, location text NOT NULL, experience_years numeric NOT NULL CHECK(experience_years>=0), availability integer NOT NULL CHECK(availability>=0), salary numeric NOT NULL CHECK(salary>0), performance_score numeric NOT NULL CHECK(performance_score BETWEEN 0 AND 100), embedding vector(1536), source_id text NOT NULL REFERENCES data_sources(id), payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS contractors (id text PRIMARY KEY, name text NOT NULL, role text NOT NULL, location text NOT NULL, rate_per_hour numeric NOT NULL CHECK(rate_per_hour>0), availability integer NOT NULL, past_performance numeric NOT NULL, embedding vector(1536), source_id text NOT NULL REFERENCES data_sources(id), payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS ats_candidates (id text PRIMARY KEY, name text NOT NULL, role text NOT NULL, location text NOT NULL, experience_years numeric NOT NULL, expected_salary numeric NOT NULL, availability integer NOT NULL, source_id text NOT NULL REFERENCES data_sources(id), embedding vector(1536), payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS employee_skills (employee_id text REFERENCES employees(id), skill_id text REFERENCES skills(id), proficiency numeric CHECK(proficiency BETWEEN 0 AND 100), years_experience numeric, PRIMARY KEY(employee_id,skill_id));
CREATE TABLE IF NOT EXISTS contractor_skills (contractor_id text REFERENCES contractors(id), skill_id text REFERENCES skills(id), proficiency numeric CHECK(proficiency BETWEEN 0 AND 100), PRIMARY KEY(contractor_id,skill_id));
CREATE TABLE IF NOT EXISTS candidate_skills (candidate_id text REFERENCES ats_candidates(id), skill_id text REFERENCES skills(id), proficiency numeric CHECK(proficiency BETWEEN 0 AND 100), PRIMARY KEY(candidate_id,skill_id));
CREATE TABLE IF NOT EXISTS requirements (id text PRIMARY KEY, owner_id text NOT NULL, role text NOT NULL, headcount integer NOT NULL CHECK(headcount>0), budget numeric NOT NULL CHECK(budget>0), deadline integer NOT NULL CHECK(deadline>0), status text NOT NULL CHECK(status IN ('Awaiting review','Approved','Rejected')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS requirement_skills (requirement_id text REFERENCES requirements(id), skill_id text REFERENCES skills(id), raw_name text NOT NULL, importance numeric NOT NULL CHECK(importance BETWEEN 0 AND 100), mandatory boolean NOT NULL, PRIMARY KEY(requirement_id,raw_name));
CREATE TABLE IF NOT EXISTS market_data (id text PRIMARY KEY, role text NOT NULL, location text NOT NULL, talent_supply numeric, avg_salary numeric, time_to_fill numeric, competition_index numeric, source_id text NOT NULL REFERENCES data_sources(id), retrieved_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS locations (city text PRIMARY KEY, country text NOT NULL, cost_index numeric, talent_index numeric, remote_score numeric, source_id text REFERENCES data_sources(id));
CREATE TABLE IF NOT EXISTS automation_profiles (id text PRIMARY KEY, role text NOT NULL, repetitive_pct numeric CHECK(repetitive_pct BETWEEN 0 AND 100), suggested_tech text[], source_id text NOT NULL REFERENCES data_sources(id));
CREATE TABLE IF NOT EXISTS strategy_scores (requirement_id text REFERENCES requirements(id), strategy text NOT NULL CHECK(strategy IN ('BUILD','BUY','BORROW','AUTOMATE','RELOCATE')), score numeric NOT NULL CHECK(score BETWEEN 0 AND 100), breakdown_json jsonb NOT NULL, weights_json jsonb NOT NULL, PRIMARY KEY(requirement_id,strategy));
CREATE TABLE IF NOT EXISTS scenarios (id text PRIMARY KEY, requirement_id text NOT NULL REFERENCES requirements(id), name text NOT NULL, inputs_json jsonb NOT NULL, cost numeric NOT NULL, time_days integer NOT NULL, risk numeric NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS decisions (id text PRIMARY KEY, requirement_id text NOT NULL UNIQUE REFERENCES requirements(id), decided_by text NOT NULL, decision text NOT NULL CHECK(decision IN ('Approved','Modified','Rejected')), comment text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS actions (id text PRIMARY KEY, requirement_id text NOT NULL REFERENCES requirements(id), decision_id text NOT NULL REFERENCES decisions(id), strategy text NOT NULL, type text NOT NULL, status text NOT NULL CHECK(status IN ('Pending','In Progress','Completed','Failed','Cancelled')), owner_name text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS decision_audit (id text PRIMARY KEY, requirement_id text NOT NULL REFERENCES requirements(id), decision_id text NOT NULL REFERENCES decisions(id), actor text NOT NULL, event jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS action_history (id text PRIMARY KEY, action_id text NOT NULL REFERENCES actions(id), actor text NOT NULL, status text NOT NULL, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS normalization_reviews (id text PRIMARY KEY, owner_id text NOT NULL, input text NOT NULL, status text NOT NULL DEFAULT 'Pending', resolved_to text REFERENCES skills(name), UNIQUE(owner_id,input));
CREATE TABLE IF NOT EXISTS projects (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE IF NOT EXISTS employee_projects (employee_id text REFERENCES employees(id), project_id text REFERENCES projects(id), PRIMARY KEY(employee_id,project_id));
CREATE TABLE IF NOT EXISTS certifications (id text PRIMARY KEY, employee_id text NOT NULL REFERENCES employees(id), name text NOT NULL, source_id text NOT NULL REFERENCES data_sources(id));
CREATE TABLE IF NOT EXISTS learning_records (id text PRIMARY KEY, employee_id text NOT NULL REFERENCES employees(id), skill_id text NOT NULL REFERENCES skills(id), progress numeric NOT NULL CHECK(progress BETWEEN 0 AND 100), estimated_days integer NOT NULL, source_id text NOT NULL REFERENCES data_sources(id), action_id text REFERENCES actions(id));
CREATE TABLE IF NOT EXISTS employee_availability (employee_id text PRIMARY KEY REFERENCES employees(id), available_after_days integer NOT NULL, source_id text NOT NULL REFERENCES data_sources(id));
CREATE TABLE IF NOT EXISTS simulator_executions (id text PRIMARY KEY, action_id text NOT NULL UNIQUE REFERENCES actions(id), system text NOT NULL, record jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS requirements_owner_idx ON requirements(owner_id,created_at DESC);
CREATE INDEX IF NOT EXISTS scenarios_requirement_idx ON scenarios(requirement_id);
CREATE INDEX IF NOT EXISTS actions_requirement_idx ON actions(requirement_id);
CREATE INDEX IF NOT EXISTS actions_decision_idx ON actions(decision_id);
CREATE INDEX IF NOT EXISTS decisions_requirement_idx ON decisions(requirement_id);
CREATE INDEX IF NOT EXISTS audit_requirement_idx ON decision_audit(requirement_id);
CREATE INDEX IF NOT EXISTS audit_decision_idx ON decision_audit(decision_id);
CREATE INDEX IF NOT EXISTS history_action_idx ON action_history(action_id);
CREATE INDEX IF NOT EXISTS employee_skills_skill_idx ON employee_skills(skill_id);
CREATE INDEX IF NOT EXISTS contractor_skills_skill_idx ON contractor_skills(skill_id);
CREATE INDEX IF NOT EXISTS candidate_skills_skill_idx ON candidate_skills(skill_id);
CREATE INDEX IF NOT EXISTS requirement_skills_skill_idx ON requirement_skills(skill_id);
CREATE INDEX IF NOT EXISTS market_source_idx ON market_data(source_id);
CREATE INDEX IF NOT EXISTS employees_source_idx ON employees(source_id);
CREATE INDEX IF NOT EXISTS contractors_source_idx ON contractors(source_id);
CREATE INDEX IF NOT EXISTS candidates_source_idx ON ats_candidates(source_id);
CREATE INDEX IF NOT EXISTS learning_employee_idx ON learning_records(employee_id);
CREATE INDEX IF NOT EXISTS learning_skill_idx ON learning_records(skill_id);
CREATE INDEX IF NOT EXISTS certifications_employee_idx ON certifications(employee_id);
CREATE INDEX IF NOT EXISTS employees_embedding_idx ON employees USING hnsw (embedding vector_cosine_ops);
CREATE INDEX IF NOT EXISTS contractors_embedding_idx ON contractors USING hnsw (embedding vector_cosine_ops);
CREATE INDEX IF NOT EXISTS candidates_embedding_idx ON ats_candidates USING hnsw (embedding vector_cosine_ops);
CREATE OR REPLACE FUNCTION reject_audit_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit records are immutable'; END; $$;
DROP TRIGGER IF EXISTS decision_audit_immutable ON decision_audit;
CREATE TRIGGER decision_audit_immutable BEFORE UPDATE OR DELETE ON decision_audit FOR EACH ROW EXECUTE FUNCTION reject_audit_change();
DROP TRIGGER IF EXISTS decisions_immutable ON decisions;
CREATE TRIGGER decisions_immutable BEFORE UPDATE OR DELETE ON decisions FOR EACH ROW EXECUTE FUNCTION reject_audit_change();
DROP TRIGGER IF EXISTS action_history_immutable ON action_history;
CREATE TRIGGER action_history_immutable BEFORE UPDATE OR DELETE ON action_history FOR EACH ROW EXECUTE FUNCTION reject_audit_change();
ALTER TABLE requirements ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS owner_requirements ON requirements;
CREATE POLICY owner_requirements ON requirements USING(owner_id=current_setting('app.user_id',true)) WITH CHECK(owner_id=current_setting('app.user_id',true));
-- The browser has no direct database connection. API checks ownership on every nested resource.
-- Production uses a dedicated non-owner application role; see db/002_access.sql.
INSERT INTO schema_migrations(version) VALUES('001') ON CONFLICT DO NOTHING;
